export function priceProgressiveUnits(units, tiers) {
    if (!Number.isSafeInteger(units) || units < 0 || !Array.isArray(tiers) || !tiers.length) throw Error('input');
    let prev = 0, total = 0;
    for (let i = 0; i < tiers.length; i++) { const t = tiers[i]; if (!t || !Number.isSafeInteger(t.rate) || t.rate < 0 || (i === tiers.length - 1 ? t.end !== null : !Number.isSafeInteger(t.end) || t.end <= prev)) throw Error('tier');
      total += Math.max(0, Math.min(units, t.end ?? units) - prev) * t.rate; if (!Number.isSafeInteger(total)) throw Error('overflow'); prev = t.end ?? units; }
    return total;
  }

export function decideWeightedQuorum(votes, threshold) {
   if (!Array.isArray(votes) || !Number.isSafeInteger(threshold) || threshold <= 0) throw Error('input');
   const seen = new Set(); let yesWeight=0,noWeight=0,abstain=0;
   for (const v of votes) { if (!v || typeof v.id!=='string' || !v.id || seen.has(v.id) || !Number.isSafeInteger(v.weight) || v.weight<=0 || !['yes','no','abstain'].includes(v.stance)) throw Error('vote'); seen.add(v.id); if(v.stance==='yes')yesWeight+=v.weight; else if(v.stance==='no')noWeight+=v.weight; else abstain+=v.weight; }
   if(!Number.isSafeInteger(yesWeight+noWeight+abstain))throw Error('overflow');
   return {yesWeight,noWeight,decision:yesWeight>=threshold?'allow':yesWeight+abstain<threshold?'deny':'pending'};
 }

export function parseIpv4Cidr(text) {
  if(typeof text!=='string'||!/^\d+\.\d+\.\d+\.\d+\/(0|[1-9]\d?)$/.test(text))throw Error('syntax');
  const [ip,p]=text.split('/'), octets=ip.split('.'); if(octets.some(x=>! /^(0|[1-9]\d{0,2})$/.test(x)||Number(x)>255)||Number(p)>32)throw Error('range');
  const n=octets.reduce((a,x)=>a*256+Number(x),0),size=2**(32-Number(p)),start=Math.floor(n/size)*size;
  const format=n=>[24,16,8,0].map(bits=>Math.floor(n/2**bits)%256).join('.');return {network:format(start),broadcast:format(start+size-1),size};
 }

export function unfoldContinuationLines(text) {
