export function canReserveCapacity(bookings,request,capacity) {
  if(!Array.isArray(bookings)||!Number.isSafeInteger(capacity)||capacity<=0)throw Error('input');
  const peak=rows=>{const events=[];for(const r of rows){if(!Array.isArray(r)||r.length!==3||!r.every(Number.isSafeInteger)||r[0]<0||r[1]<=r[0]||r[2]<=0)throw Error('booking');events.push([r[0],r[2]],[r[1],-r[2]]);}events.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);let n=0,m=0;for(const e of events){n+=e[1];if(!Number.isSafeInteger(n))throw Error('overflow');m=Math.max(m,n);}return m;};
  if(peak(bookings)>capacity)throw Error('original');return peak([...bookings,request])<=capacity;
 }

export function distributeDebit(balances,amount) {
  if(!Array.isArray(balances)||balances.some(x=>!Number.isSafeInteger(x)||x<0)||!Number.isSafeInteger(amount)||amount<0)throw Error('input');const total=balances.reduce((a,b)=>a+b,0);if(!Number.isSafeInteger(total))throw Error('overflow');
  if(total<amount)return {ok:false,balances:[...balances]};let left=amount;return {ok:true,balances:balances.map(x=>{const taken=Math.min(left,x);left-=taken;return x-taken;})};
 }

export function instantRunoffWinner(candidates,ballots) {
  if(!Array.isArray(candidates)||!candidates.length||candidates.some(x=>typeof x!=='string'||!x)||new Set(candidates).size!==candidates.length||!Array.isArray(ballots))throw Error('input');
  if(ballots.some(b=>!Array.isArray(b)||!b.length||new Set(b).size!==b.length||b.some(x=>!candidates.includes(x))))throw Error('ballot');const active=new Set(candidates);
  while(active.size){const counts=new Map([...active].map(x=>[x,0]));let total=0;for(const b of ballots){const first=b.find(x=>active.has(x));if(first!==undefined){counts.set(first,counts.get(first)+1);total++;}}if(!total)return null;for(const [x,n] of counts)if(n>total/2)return x;
  const loser=[...active].sort((a,b)=>counts.get(a)-counts.get(b)||(a<b?1:a>b?-1:0))[0];active.delete(loser);}return null;
 }

export function minimumWatermark(sources,required) {
  if(!Array.isArray(sources)||!Array.isArray(required)||required.some(x=>typeof x!=='string'||!x)||new Set(required).size!==required.length)throw Error('input');const map=new Map();
  for(const s of sources){if(!s||typeof s.id!=='string'||!s.id||map.has(s.id)||!Number.isSafeInteger(s.watermark)||s.watermark<0)throw Error('source');map.set(s.id,s.watermark);}return !required.length||required.some(id=>!map.has(id))?null:Math.min(...required.map(id=>map.get(id)));
 }

export function expandMinuteSchedule(expression) {
  if(typeof expression!=='string'||!expression)throw Error('input');const out=new Set(),num=s=>{if(!/^(0|[1-9]\d?)$/.test(s)||+s>59)throw Error('number');return +s;};
  for(const term of expression.split(',')){const parts=term.split('/');if(parts.length>2)throw Error('term');const range=parts[0],step=parts.length===2?num(parts[1]):1;if(step===0)throw Error('step');let a,b;if(range==='*'){a=0;b=59;}else if(range.includes('-')){const ends=range.split('-');if(ends.length!==2)throw Error('range');a=num(ends[0]);b=num(ends[1]);}else{if(parts.length===2)throw Error('step');a=b=num(range);}if(a>b)throw Error('range');for(let n=a;n<=b;n+=step)out.add(n);}return [...out].sort((a,b)=>a-b);
 }

export function isoWeekDate(year,week,weekday) {
  if(![year,week,weekday].every(Number.isInteger)||year<100||year>9999||week<1||week>53||weekday<1||weekday>7)throw Error('input');
  const jan4=new Date(Date.UTC(year,0,4));const monday=jan4.getTime()-((jan4.getUTCDay()+6)%7)*86400000;const target=new Date(monday+((week-1)*7+weekday-1)*86400000),thursday=new Date(target.getTime()+(4-((target.getUTCDay()+6)%7+1))*86400000);
  if(thursday.getUTCFullYear()!==year||target.getUTCFullYear()<100||target.getUTCFullYear()>9999)throw Error('week');return target.toISOString().slice(0,10);
 }

export function netAccountTransfers(transfers) {
  if(!Array.isArray(transfers))throw Error('input');const seen=new Set(),sums=new Map();for(const t of transfers){if(!t||['id','from','to'].some(k=>typeof t[k]!=='string'||!t[k])||seen.has(t.id)||t.from===t.to||!Number.isSafeInteger(t.amount)||t.amount<=0)throw Error('transfer');seen.add(t.id);for(const [a,n] of [[t.from,-t.amount],[t.to,t.amount]]){const v=(sums.get(a)||0)+n;if(!Number.isSafeInteger(v))throw Error('overflow');sums.set(a,v);}}return [...sums.keys()].sort().map(account=>({account,net:sums.get(account)}));
 }

export function selectFeatureRule(rules,context) {
  const record=x=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.values(x).every(v=>typeof v==='string');if(!Array.isArray(rules)||!record(context))throw Error('input');const ids=new Set(),matches=[];
  for(const r of rules){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Number.isSafeInteger(r.priority)||typeof r.enabled!=='boolean'||!record(r.when))throw Error('rule');ids.add(r.id);if(Object.entries(r.when).every(([k,v])=>Object.hasOwn(context,k)&&context[k]===v))matches.push(r);}
  matches.sort((a,b)=>b.priority-a.priority||Object.keys(b.when).length-Object.keys(a.when).length||(a.id<b.id?-1:a.id>b.id?1:0));return matches.length?{id:matches[0].id,enabled:matches[0].enabled}:null;
 }
